    '        totalamount_total += Number(model.getValue(record, "TOTALAMOUNT"));',
    '    }',
    '});',
    '',
    '',
    '$s(''P171_SUMOFAMOUNT'',amount_total);',
    '$s(''P171_SUMOFFOOTERAMOUNT'',footeramount_total);',
    '$s(''P171_SALESORDERAMOUNT'',totalamount_total);',
    '',
    '},400',
    ');',
